def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Uniform non-background rows/columns are repeating-tile separators.
    row_lines = [r for r in range(h)
                 if all(v == grid[r][0] for v in grid[r]) and grid[r][0] != bg]
    col_lines = [c for c in range(w)
                 if all(grid[r][c] == grid[0][c] for r in range(h))
                 and grid[0][c] != bg]
    row_period = row_lines[0] + 1 if row_lines else h
    col_period = col_lines[0] + 1 if col_lines else w

    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if r in row_lines or c in col_lines:
                out[r][c] = grid[r][c]
            elif grid[r][c] != bg:
                for rr in range(r % row_period, h, row_period):
                    for cc in range(c % col_period, w, col_period):
                        if rr not in row_lines and cc not in col_lines:
                            out[rr][cc] = grid[r][c]
    return out
